"""Linux-only private MySQL8.4 processes, explicit GTIDs and loopback replication."""
import os,sys,pathlib,subprocess,socket,time,threading,signal,shutil,contextlib,secrets
import pymysql

LAUNCH='''import os,sys,ctypes,signal
expected=int(sys.argv[1]);libc=ctypes.CDLL(None,use_errno=True)
libc.prctl.restype=ctypes.c_int
libc.prctl.argtypes=[ctypes.c_int,ctypes.c_ulong,ctypes.c_ulong,ctypes.c_ulong,ctypes.c_ulong]
if libc.prctl(1,int(signal.SIGKILL),0,0,0)!=0 or os.getppid()!=expected:raise SystemExit(91)
os.execv(sys.argv[2],sys.argv[2:])
'''
def free_port():
 with socket.socket() as s:s.bind(('127.0.0.1',0));return s.getsockname()[1]
def execute(connection,sql,args=None):
 with connection.cursor() as cursor:cursor.execute(sql,args);return cursor.fetchall()
def scalar(connection,sql,args=None):return execute(connection,sql,args)[0][0]

class Guarded:
 def __init__(self,args,root,name,seconds=100):self.args=args;self.root=root;self.name=name;self.seconds=seconds;self.proc=None;self.thread=None;self.log=None;self.stop=threading.Event();self.error=None;self.peak=0
 def __enter__(self):
  self.log=(self.root/(self.name+'.log')).open('wb');self.proc=subprocess.Popen([sys.executable,'-B','-c',LAUNCH,str(os.getpid()),*self.args],cwd=self.root,stdout=self.log,stderr=self.log,start_new_session=True)
  started=time.monotonic()
  def watch():
   missing=0
   while not self.stop.wait(.08):
    if self.proc.poll() is not None:return
    try:
     lines=pathlib.Path('/proc/'+str(self.proc.pid)+'/status').read_text().splitlines();value=next((int(line.split()[1])*1024 for line in lines if line.startswith('VmRSS:')),None)
     if value is None:
      missing+=1
      if missing<6:continue
      raise RuntimeError('owned MySQL RSS unavailable')
     missing=0;self.peak=max(self.peak,value)
     if value>384*1048576 or time.monotonic()-started>self.seconds:raise RuntimeError('owned MySQL exceeded RSS/wall budget')
    except FileNotFoundError:return
    except Exception as error:
     if self.proc.poll() is None:self.error=str(error);os.killpg(self.proc.pid,signal.SIGKILL)
     return
  self.thread=threading.Thread(target=watch,daemon=True);self.thread.start();return self
 def __exit__(self,*args):
  self.stop.set()
  if self.proc and self.proc.poll() is None:
   os.killpg(self.proc.pid,signal.SIGTERM)
   try:self.proc.wait(5)
   except subprocess.TimeoutExpired:os.killpg(self.proc.pid,signal.SIGKILL);self.proc.wait(3)
  if self.thread:self.thread.join(1)
  if self.log:self.log.close()
  if self.error:raise AssertionError(self.error)

class Server:
 def __init__(self,root,node):self.root=pathlib.Path(root);self.node=node;self.port=free_port();self.guard=None;self.connection=None
 def __enter__(self):
  assert sys.platform=='linux' and os.geteuid()!=0
  binary=shutil.which('mysqld');assert binary,'NATIVE_ENVIRONMENT_ERROR: mysqld missing'
  version=subprocess.check_output([binary,'--no-defaults','--version'],timeout=4).decode()
  assert '8.4.' in version and 'MariaDB' not in version,'NATIVE_ENVIRONMENT_ERROR: real MySQL8.4 required'
  self.root.mkdir(parents=True,exist_ok=False);exports=self.root/'exports';exports.mkdir();base=pathlib.Path(binary).resolve().parent.parent
  args=[binary,'--no-defaults','--basedir='+str(base),'--datadir='+str(self.root/'data'),'--innodb-buffer-pool-size=64M','--performance-schema=OFF','--innodb-redo-log-capacity=16M','--innodb-log-buffer-size=4M','--innodb-doublewrite=OFF','--mysqlx=OFF','--max-connections=12','--table-open-cache=32','--table-open-cache-instances=1','--table-definition-cache=400','--thread-cache-size=0','--innodb-read-io-threads=1','--innodb-write-io-threads=1','--innodb-purge-threads=1','--tmp-table-size=1M','--max-heap-table-size=1M','--local-infile=OFF','--secure-file-priv='+str(exports),'--server-id='+str(self.node),'--gtid-mode=ON','--enforce-gtid-consistency=ON','--log-bin='+str(self.root/'binlog'),'--relay-log='+str(self.root/'relay'),'--log-replica-updates=ON','--replica-parallel-workers=1','--skip-replica-start','--binlog-expire-logs-seconds=3600']
  with Guarded(args+['--initialize-insecure','--skip-networking'],self.root,'initialize',40) as initial:
   initial.proc.wait(30);assert initial.proc.returncode==0,(self.root/'initialize.log').read_text(errors='replace')[-2500:]
  try:
   self.guard=Guarded(args+['--bind-address=127.0.0.1','--port='+str(self.port),'--socket='+str(self.root/'mysql.sock'),'--pid-file='+str(self.root/'mysql.pid'),'--max-execution-time=5000'],self.root,'server').__enter__()
   deadline=time.monotonic()+12
   while self.connection is None:
    try:self.connection=self.connect()
    except pymysql.Error:
     assert self.guard.proc.poll() is None and time.monotonic()<deadline,(self.root/'server.log').read_text(errors='replace')[-2500:]
     time.sleep(.08)
   assert int((self.root/'mysql.pid').read_text())==self.guard.proc.pid,'server escaped owned PID'
   print('NATIVE_MYSQL_GTID_SERVER_READY:'+str(self.node),flush=True);return self
  except BaseException:self.__exit__(None,None,None);raise
 def connect(self,user='root',password=''):return pymysql.connect(host='127.0.0.1',port=self.port,user=user,password=password,charset='utf8mb4',autocommit=True,connect_timeout=1,read_timeout=7,write_timeout=3,local_infile=False)
 def status(self):
  with self.connection.cursor(pymysql.cursors.DictCursor) as cursor:cursor.execute('SHOW REPLICA STATUS');return cursor.fetchone()
 def follow(self,source,user,password):
  execute(self.connection,'CHANGE REPLICATION SOURCE TO SOURCE_HOST=%s,SOURCE_PORT=%s,SOURCE_USER=%s,SOURCE_PASSWORD=%s,SOURCE_AUTO_POSITION=1,GET_SOURCE_PUBLIC_KEY=1,SOURCE_SSL=0',('127.0.0.1',source.port,user,password));execute(self.connection,'START REPLICA')
 def sync(self,source):
  target=scalar(source.connection,'SELECT @@GLOBAL.gtid_executed');assert scalar(self.connection,'SELECT WAIT_FOR_EXECUTED_GTID_SET(%s,4)',(target,))==0,self.status();return target
 def __exit__(self,*args):
  if self.connection:
   try:execute(self.connection,'SHUTDOWN')
   except pymysql.Error:pass
   self.connection.close();self.connection=None
  if self.guard:self.guard.__exit__(*args);self.guard=None
  with socket.socket() as s:assert s.connect_ex(('127.0.0.1',self.port))!=0,'private MySQL port remained open'

def provision(source):
 secret=secrets.token_hex(16)
 execute(source.connection,"CREATE USER 'delivery'@'127.0.0.1' IDENTIFIED BY %s",(secret,));execute(source.connection,"GRANT REPLICATION SLAVE ON *.* TO 'delivery'@'127.0.0.1'")
 return 'delivery',secret
